let DATA = null;

function t(key) {
  const d = STR[getLang()];
  return Object.prototype.hasOwnProperty.call(d, key) ? d[key] : key;
}

function applyStaticI18n() {
  document.documentElement.lang = getLang();
  document.title = t("title");
  document.querySelectorAll("[data-i18n]").forEach((el) => { el.textContent = t(el.dataset.i18n); });
  document.querySelectorAll("[data-i18n-html]").forEach((el) => { el.innerHTML = t(el.dataset.i18nHtml); });
  document.querySelectorAll("[data-i18n-aria-label]").forEach((el) => { el.setAttribute("aria-label", t(el.dataset.i18nAriaLabel)); });
  const btn = document.getElementById("langToggleBtn");
  if (btn) btn.textContent = getLang() === "pl" ? "EN" : "PL";
}

// --- tiny SVG helpers -------------------------------------------------------
const esc = (s) => String(s).replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
const rect = (x, y, w, h, fill, extra = "") =>
  `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${Math.max(0, w).toFixed(1)}" height="${Math.max(0, h).toFixed(1)}" fill="${fill}" ${extra}/>`;
const line = (x1, y1, x2, y2, cls) =>
  `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" class="${cls}"/>`;
const text = (x, y, s, cls = "", anchor = "start") =>
  `<text x="${x.toFixed(1)}" y="${y.toFixed(1)}" class="${cls}" text-anchor="${anchor}">${esc(s)}</text>`;

function setSvg(id, inner, vb) {
  const el = document.getElementById(id);
  if (!el) return;
  if (vb) el.setAttribute("viewBox", vb);
  el.innerHTML = inner;
}

function legend(id, items) {
  const el = document.getElementById(id);
  if (!el) return;
  el.innerHTML = items
    .map((it) => `<span class="item"><span class="swatch" style="background:${it.c}"></span>${esc(it.l)}</span>`)
    .join("");
}

// --- section 1: per-city ring small multiples ------------------------------
function ringCell(city) {
  const res = city.resolutions["250"] || city.resolutions["500"];
  const rings = res.rings.filter((r) => r.pop > 0 || Math.abs(r.mean) > 0.01);
  const w = 224, h = 132, m = { t: 6, r: 6, b: 30, l: 24 };
  const iw = w - m.l - m.r, ih = h - m.t - m.b;
  const maxAbs = Math.max(1, Math.ceil(Math.max(...rings.map((r) => Math.abs(r.mean)))));
  const y0 = m.t + ih * 0.5;
  const yFor = (v) => m.t + ih * (1 - (v + maxAbs) / (2 * maxAbs));
  const bw = (iw / rings.length) * 0.78;
  let s = "";
  s += line(m.l, y0, m.l + iw, y0, "axis");
  s += line(m.l, m.t, m.l, m.t + ih, "axis");
  s += text(m.l - 3, y0 + 3, "0", "val", "end");
  s += text(m.l - 3, m.t + 7, "+" + maxAbs, "val", "end");
  s += text(m.l - 3, m.t + ih, "−" + maxAbs, "val", "end");
  const tickAt = new Set([0, Math.floor((rings.length - 1) / 2), rings.length - 1]);
  rings.forEach((r, i) => {
    const cx = m.l + (i + 0.5) * (iw / rings.length);
    const v = Math.max(-maxAbs, Math.min(maxAbs, r.mean));
    const yv = yFor(v);
    const fill = r.mean >= 0 ? COL.pos : COL.neg;
    s += rect(cx - bw / 2, Math.min(y0, yv), bw, Math.abs(yv - y0), fill);
    if (tickAt.has(i)) {
      s += text(cx, m.t + ih + 12, String(Math.round(r.hi)), "val", "middle");
    }
  });
  s += text(m.l + iw / 2, h - 4, t("kmAxis"), "val", "middle");
  const dipRes = ["250", "500"].some((k) => city.resolutions[k] && city.resolutions[k].dip);
  return (
    `<div class="ring-cell">` +
    `<div class="ring-title"><span>${esc(CITY_PL[city.key] || city.label)}</span>` +
    `<span class="ring-verdict ${dipRes ? "dip" : "nodip"}">${dipRes ? t("dipYes") : t("dipNo")}</span></div>` +
    `<svg viewBox="0 0 ${w} ${h}" width="100%">${s}</svg></div>`
  );
}

function renderRings() {
  document.getElementById("ringGrid").innerHTML = DATA.cities.map(ringCell).join("");
}

// --- section 2: net delta per city, 250 vs 500 ----------------------------
function renderNet() {
  legend("netLegend", [{ c: COL.pos, l: t("leg250") }, { c: COL.posSoft, l: t("leg500") }]);
  const W = 720, m = { t: 14, r: 46, b: 24, l: 96 };
  const cities = DATA.cities;
  const rowH = 44, H = m.t + m.b + cities.length * rowH;
  const vals = [];
  cities.forEach((c) => ["250", "500"].forEach((k) => c.resolutions[k] && vals.push(c.resolutions[k].net)));
  const lo = Math.min(-1, Math.floor(Math.min(...vals)));
  const hi = Math.max(1, Math.ceil(Math.max(...vals)));
  const iw = W - m.l - m.r;
  const xFor = (v) => m.l + iw * (v - lo) / (hi - lo);
  const x0 = xFor(0);
  let s = "";
  for (let g = lo; g <= hi; g++) {
    s += line(xFor(g), m.t, xFor(g), H - m.b, g === 0 ? "axis" : "grid");
    s += text(xFor(g), H - m.b + 14, (g > 0 ? "+" : "") + g, "val", "middle");
  }
  cities.forEach((c, i) => {
    const cy = m.t + i * rowH;
    s += text(m.l - 8, cy + rowH / 2 + 4, CITY_PL[c.key] || c.label, "lbl", "end");
    const bars = ["250", "500"].filter((k) => c.resolutions[k]);
    bars.forEach((k, bi) => {
      const v = c.resolutions[k].net;
      const bh = 13;
      const by = cy + 8 + bi * (bh + 3);
      const fill = k === "250" ? COL.pos : COL.posSoft;
      s += rect(Math.min(x0, xFor(v)), by, Math.abs(xFor(v) - x0), bh, fill);
      // label always to the right: past the bar end for positives, just right of
      // the zero line for negatives (their bar sits left of it) -- keeps short
      // negative bars from colliding with the city name in the left gutter.
      const lx = v >= 0 ? xFor(v) + 4 : x0 + 4;
      s += text(lx, by + bh - 2.5, (v > 0 ? "+" : "") + v.toFixed(2), "val", "start");
    });
  });
  setSvg("netChart", s, `0 0 ${W} ${H}`);
}

// --- section 3: tram/bus early-vs-late diverging --------------------------
function renderShift() {
  legend("shiftLegend", [{ c: COL.pos, l: t("legEarly") }, { c: COL.neg, l: t("legLate") }]);
  const cities = DATA.cities.filter((c) => c.shift_peak);
  const W = 720, m = { t: 14, r: 24, b: 24, l: 150 };
  const grpH = 60, H = m.t + m.b + cities.length * grpH;
  const iw = W - m.l - m.r;
  const mid = m.l + iw / 2;
  const maxPct = 55;
  const xFor = (p) => (p / maxPct) * (iw / 2);
  let s = "";
  s += line(mid, m.t, mid, H - m.b, "axis");
  [50, 25].forEach((p) => {
    s += line(mid - xFor(p), m.t, mid - xFor(p), H - m.b, "grid");
    s += line(mid + xFor(p), m.t, mid + xFor(p), H - m.b, "grid");
    s += text(mid - xFor(p), H - m.b + 14, p + "%", "val", "middle");
    s += text(mid + xFor(p), H - m.b + 14, p + "%", "val", "middle");
  });
  s += text(mid, H - m.b + 14, "0", "val", "middle");
  cities.forEach((c, i) => {
    const gy = m.t + i * grpH;
    s += text(6, gy + grpH / 2 + 4, CITY_PL[c.key] || c.label, "lbl", "start");
    [["tram", t("tram")], ["autobus", t("bus")]].forEach(([mode, lbl], mi) => {
      const d = c.shift_peak[mode];
      if (!d) return;
      const bh = 15;
      const by = gy + 8 + mi * (bh + 6);
      const yTxt = by + bh - 3;
      s += text(m.l - 10, yTxt, lbl, "val", "end");
      s += rect(mid - xFor(d.early_pct), by, xFor(d.early_pct), bh, COL.pos);
      s += rect(mid, by, xFor(d.late_pct), bh, COL.neg);
      const showEarly = d.early_pct >= 0.5, showLate = d.late_pct >= 0.5;
      if (showEarly) s += text(mid - xFor(d.early_pct) - 4, yTxt, Math.round(d.early_pct) + "%", "val", "end");
      if (showLate) s += text(mid + xFor(d.late_pct) + 4, yTxt, Math.round(d.late_pct) + "%", "val", "start");
      if (!showEarly && !showLate) s += text(mid + 6, yTxt, "0%", "val", "start");
    });
  });
  setSvg("shiftChart", s, `0 0 ${W} ${H}`);
}

// --- section 4: comparable-hexagon breakdown -----------------------------
function renderHex() {
  legend("hexLegend", [
    { c: COL.pos, l: t("legGain") },
    { c: COL.neg, l: t("legLoss") },
    { c: COL.neutral, l: t("legUnchanged") },
  ]);
  const W = 720, m = { t: 14, r: 150, b: 14, l: 96 };
  const cities = DATA.cities;
  const rowH = 46, H = m.t + m.b + cities.length * rowH;
  const iw = W - m.l - m.r;
  let s = "";
  cities.forEach((c, i) => {
    const res = c.resolutions["250"] || c.resolutions["500"];
    const hx = res.hex;
    const comp = hx.gain + hx.loss + hx.unchanged;
    const cy = m.t + i * rowH;
    s += text(m.l - 8, cy + rowH / 2 + 4, CITY_PL[c.key] || c.label, "lbl", "end");
    const bh = 16, by = cy + 8;
    let x = m.l;
    [["gain", COL.pos], ["loss", COL.neg], ["unchanged", COL.neutral]].forEach(([k, col]) => {
      const w = iw * (hx[k] / comp);
      s += rect(x, by, w, bh, col);
      x += w;
    });
    const wMean = res.net, uMean = res.net_unweighted;
    s += text(m.l + iw + 8, by + bh - 3,
      `${hx.gain} / ${hx.loss} / ${hx.unchanged}`, "val", "start");
    s += text(m.l + iw + 8, cy + rowH - 4,
      `${(wMean > 0 ? "+" : "")}${wMean.toFixed(2)} · ${(uMean > 0 ? "+" : "")}${uMean.toFixed(2)}`, "val", "start");
  });
  setSvg("hexChart", s, `0 0 ${W} ${H}`);
}

// --- section 5: compute table -------------------------------------------
function renderCompute() {
  const order = ["szczecin", "gdansk", "poznan", "krakow", "warszawa", "lodz"];
  const byKey = Object.fromEntries(DATA.cities.map((c) => [c.key, c]));
  let rows = `<thead><tr><th>${esc(t("thCity"))}</th><th>${esc(t("thWall"))}</th><th>${esc(t("thNote"))}</th></tr></thead><tbody>`;
  order.forEach((k) => {
    const c = byKey[k];
    if (!c) return;
    const cm = c.compute || {};
    const note = cm.note && typeof cm.note === "object" ? (cm.note[getLang()] || cm.note.pl || "") : (cm.note || "");
    rows += `<tr><td>${esc(CITY_PL[k] || c.label)}</td><td>${esc(cm.wall || "—")}</td><td>${esc(note)}</td></tr>`;
  });
  rows += "</tbody>";
  document.getElementById("computeTable").innerHTML = rows;
}

function renderAll() {
  applyStaticI18n();
  if (!DATA) return;
  renderRings();
  renderNet();
  renderShift();
  renderHex();
  renderCompute();
}

document.addEventListener("DOMContentLoaded", () => {
  applyStaticI18n();
  const btn = document.getElementById("langToggleBtn");
  if (btn) {
    btn.addEventListener("click", () => {
      localStorage.setItem(LANG_KEY, getLang() === "pl" ? "en" : "pl");
      renderAll();
    });
  }
  fetch("report_data.json")
    .then((r) => r.json())
    .then((d) => { DATA = d; renderAll(); })
    .catch(() => {
      document.getElementById("ringGrid").innerHTML =
        '<p class="sub">Nie udało się wczytać danych (report_data.json).</p>';
    });
});
